package com.solarmind.service; import com.solarmind.config.AiProperties; import com.solarmind.dto.request.AskRequest; import com.solarmind.dto.response.AskResponse; import com.solarmind.exception.AiServiceUnavailableException; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*;
@Service public class AIService { private final RestClient client; private final AiProperties properties; private final AssessmentService assessments; public AIService(RestClient client,AiProperties properties,AssessmentService assessments){this.client=client;this.properties=properties;this.assessments=assessments;} public AskResponse ask(AskRequest r){Object context=r.assessmentId()==null?Map.of():assessments.get(r.assessmentId()); try{return client.post().uri(properties.serviceUrl()+"/api/ai/ask").header("X-Internal-Token",properties.internalToken()).body(Map.of("question",r.question(),"context",context)).retrieve().body(AskResponse.class);}catch(Exception e){throw new AiServiceUnavailableException("AI service is unavailable");}} }
